    def __init__(self, value):
        self.value = value
        self.neighbors = []

def construct_graph(edges):
    graph = {}
    for edge in edges:
        node1, node2 = edge
        if node1 not in graph:
            graph[node1] = GraphNode(node1)
        if node2 not in graph:
            graph[node2] = GraphNode(node2)
        graph[node1].neighbors.append(graph[node2])
    return graph

def dfs(graph, start, target, visited=None):
